<template>
  <div class="app-container">
    <el-alert title="系统配置直接写入若依 sys_config。未有后端配置契约的分组不会显示可保存表单。" type="info" :closable="false" />
    <el-tabs v-model="tab" @tab-click="load">
      <el-tab-pane label="查券设置" name="coupon">
        <el-table v-loading="loading" :data="configs"><el-table-column label="配置项" prop="configName" min-width="180"/><el-table-column label="配置键" prop="configKey" min-width="240"/><el-table-column label="当前值" prop="configValue" min-width="220" show-overflow-tooltip/><el-table-column label="操作" width="90"><template slot-scope="s"><el-button type="text" size="mini" @click="editConfig(s.row)" v-hasPermi="['system:config:edit']">编辑</el-button></template></el-table-column></el-table>
      </el-tab-pane>
      <el-tab-pane label="结算与冻结" name="settlement">
        <el-alert title="配置将追加一个结算版本，历史订单按付款时有效版本读取。冻结时长按秒填写；所有平台均需显式配置。" type="warning" :closable="false" />
        <el-table v-loading="historyLoading" :data="history" style="margin-top:12px"><el-table-column label="版本" prop="id" width="90"/><el-table-column label="生效时间" prop="effectiveAt" min-width="190"/><el-table-column label="平台冻结档位" min-width="320"><template slot-scope="s">{{ freezeSummary(s.row.settings) }}</template></el-table-column><el-table-column label="最低付款金额" min-width="130"><template slot-scope="s">¥{{s.row.settings.minimumPaid}}</template></el-table-column><el-table-column label="最低佣金" min-width="120"><template slot-scope="s">¥{{s.row.settings.minimumCommission}}</template></el-table-column><el-table-column label="最大奖励" min-width="120"><template slot-scope="s">¥{{s.row.settings.maximumReward}}</template></el-table-column></el-table>
        <el-button type="primary" size="mini" style="margin-top:12px" @click="editFreeze" v-hasPermi="['system:commission:rule:edit']">编辑并发布冻结配置</el-button>
      </el-tab-pane>
      <el-tab-pane label="奖励与邀请" name="rewards"><el-empty description="奖励配置由返佣规则的版本化 Incentive 设置管理。新用户首次进入、首单、邀请、下单里程碑等类型在返佣设置页编辑。" /></el-tab-pane>
      <el-tab-pane label="其他系统配置" name="other"><el-empty description="无主订单保留期、邀请码起始值、邀请层级等尚无稳定的专用配置契约，当前不提供可保存控件。" /></el-tab-pane>
    </el-tabs>
    <el-dialog title="编辑配置" :visible.sync="configOpen" width="650px" append-to-body><el-form :model="configForm" label-width="150px"><el-form-item label="配置名称"><el-input v-model="configForm.configName" disabled/></el-form-item><el-form-item label="配置键"><el-input v-model="configForm.configKey" disabled/></el-form-item><el-form-item label="配置值"><el-input v-model="configForm.configValue" type="textarea" :rows="4"/></el-form-item><el-form-item label="备注"><el-input v-model="configForm.remark" type="textarea" :rows="2"/></el-form-item></el-form><div slot="footer"><el-button type="primary" :loading="saving" @click="saveConfig">保存</el-button><el-button @click="configOpen=false">取消</el-button></div></el-dialog>
    <el-dialog title="结算冻结配置" :visible.sync="freezeOpen" width="900px" append-to-body :close-on-click-modal="false"><el-form :model="freezeForm" label-width="190px"><el-form-item label="最低付款金额 (元)"><el-input v-model="freezeForm.minimumPaid"/></el-form-item><el-form-item label="最低联盟佣金 (元)"><el-input v-model="freezeForm.minimumCommission"/></el-form-item><el-form-item label="最大单笔奖励 (元)"><el-input v-model="freezeForm.maximumReward"/></el-form-item><el-form-item label="会员可关闭冻结"><el-switch v-model="freezeForm.userDisabledFreeze"/></el-form-item><div v-for="p in platformKeys" :key="p" class="platform-box"><h4>{{ platformLabel(p) }}冻结档位</h4><el-table :data="freezeForm.tiers[p]" border size="mini"><el-table-column label="返利门槛 (元)" min-width="180"><template slot-scope="s"><el-input v-model="s.row.minimumAmount"/></template></el-table-column><el-table-column label="冻结秒数" min-width="180"><template slot-scope="s"><el-input-number v-model="s.row.seconds" :min="0" :precision="0"/></template></el-table-column><el-table-column label="操作" width="80"><template slot-scope="s"><el-button type="text" @click="freezeForm.tiers[p].splice(s.$index,1)">删除</el-button></template></el-table-column></el-table><el-button size="mini" plain style="margin-top:8px" @click="freezeForm.tiers[p].push({minimumAmount:'',seconds:null})">添加档位</el-button><el-form-item :label="platformLabel(p)+'快速冻结秒数'" style="margin-top:12px"><el-input-number v-model="freezeForm.fastSeconds[p]" :min="0" :precision="0"/></el-form-item></div></el-form><div slot="footer"><el-button type="primary" :loading="saving" @click="saveFreeze">发布配置版本</el-button><el-button @click="freezeOpen=false">取消</el-button></div></el-dialog>
  </div>
</template>
<script>
import { getCpsConfigList, getCpsConfig, saveCpsConfig, settlementHistory, publishSettlement, cpsDict } from '@/api/cps/settings'
const KEYS = ['cps.coupon.cache-seconds','cps.coupon.minimum-commission','cps.coupon.message.no-commission','cps.coupon.show-no-commission','cps.coupon.message.low-commission','cps.coupon.message.pdd-comparison','cps.coupon.show-pdd-comparison','cps.coupon.binding-notice-minutes','cps.coupon.message.redpacket','cps.coupon.message.old-cart','cps.coupon.message.refund','cps.coupon.jd-union-id']
export default { name:'CpsSettings', data(){return {tab:'coupon',loading:false,saving:false,configs:[],history:[],historyLoading:false,platforms:[],configOpen:false,configForm:{},freezeOpen:false,freezeForm:{minimumPaid:'',minimumCommission:'',maximumReward:'',userDisabledFreeze:null,tiers:{},fastSeconds:{}},platformKeys:[]}}, created(){cpsDict().then(r=>{this.platforms=(r.data&&r.data.platforms)||[];this.platformKeys=this.platforms.map(x=>x.value.toUpperCase())});this.load()}, methods:{load(){if(this.tab==='coupon'){this.loading=true;getCpsConfigList({pageNum:1,pageSize:200}).then(r=>{this.configs=(r.rows||[]).filter(x=>KEYS.includes(x.configKey))}).finally(()=>{this.loading=false})}if(this.tab==='settlement'){this.historyLoading=true;settlementHistory().then(r=>{this.history=r.data||[]}).finally(()=>{this.historyLoading=false})}},editConfig(row){getCpsConfig(row.configId).then(r=>{this.configForm={...r.data};this.configOpen=true})},saveConfig(){this.saving=true;saveCpsConfig(this.configForm).then(()=>{this.$modal.msgSuccess('配置保存成功');this.configOpen=false;this.load()}).finally(()=>{this.saving=false})},platformLabel(v){const x=this.platforms.find(p=>p.value.toUpperCase()===v);return x?x.label:v},freezeSummary(s){const f=(s&&s.freeze)||{};const t=f.tiers||{};return Object.keys(t).map(p=>`${p}: ${(t[p]||[]).length} 档`).join(' · ')||'未配置'},editFreeze(){const s=this.history[0]&&this.history[0].settings;if(!s){this.$modal.msgError('尚无结算配置版本，不能从空白模板发布');return}const freeze=s.freeze;this.freezeForm={minimumPaid:s.minimumPaid,minimumCommission:s.minimumCommission,maximumReward:s.maximumReward,userDisabledFreeze:freeze.userDisabledFreeze,tiers:{},fastSeconds:{...freeze.fastSeconds}};this.platformKeys.forEach(p=>{this.$set(this.freezeForm.tiers,p,(freeze.tiers[p]||[]).map(x=>({...x}))) });this.freezeOpen=true},saveFreeze(){if(this.platformKeys.some(p=>!this.freezeForm.tiers[p]||!this.freezeForm.tiers[p].length||this.freezeForm.fastSeconds[p]==null)){this.$modal.msgError('所有平台都必须配置冻结档和快速冻结秒数');return}this.$modal.confirm('保存后新版本将按付款时间应用。确认发布？').then(()=>{this.saving=true;return publishSettlement({minimumPaid:this.freezeForm.minimumPaid,minimumCommission:this.freezeForm.minimumCommission,maximumReward:this.freezeForm.maximumReward,freeze:{tiers:this.freezeForm.tiers,fastSeconds:this.freezeForm.fastSeconds,userDisabledFreeze:this.freezeForm.userDisabledFreeze}})}).then(()=>{this.$modal.msgSuccess('结算配置发布成功');this.freezeOpen=false;this.load()}).catch(()=>{}).finally(()=>{this.saving=false})}} }
</script>
<style scoped>.platform-box{border:1px solid #ebeef5;padding:12px;margin-bottom:14px}.platform-box h4{margin:0 0 10px}</style>
